List<double> rescaleToUnit(List<double> numbers) {
  final double min = numbers.reduce((a, b) => a < b ? a : b);
  final double max = numbers.reduce((a, b) => a > b ? a : b);

  if (max == min) return [1.0]; // Edge case: all values are the same.

  return List<double>.generate(numbers.length, 
      (i) => (numbers[i] - min) / (max - min));
}

