    var a = RegExp(r'(\d+)\s+apples').firstMatch(s);
    var o = RegExp(r'(\d+)\s+oranges').firstMatch(s);

    var applesCount = int.tryParse(a?.group(1) ?? '');
    var orangesCount = int.tryParse(o?.group(1) ?? '');

    if ((n % applesCount == 0 || n % orangesCount == 0) && applesCount != null && orangesCount != null) {
      print('$n is divisible by both $applesCount and $orangesCount.');

      return Math.max(n ~/ applesCount, n ~/ orangesCount); 
    } else {
      print('$n is not evenly divisible by either $applesCount or $orangesCount.');
      return 0;
    }
  } else {
    throw Exception("Invalid input string");
  }
}


