int levenshtein(String a, String b) {
  final m = a.length + 1;
  final n = b.length + 1;



  var dp = [List<int>.filled(n, -1)]; 


  for (int i = 0; i <= m; ++i) {
    dp[i] = [];
    for (int j = 0; j <= n; ++j) {

      if (i == 0) {
        dp[i][j] = j;
      } else if (j == 0) {
        dp[i][j] = i;
      } else if (a.substring(i - 1, i).toLowerCase() == b.substring(j - 1, j).toLowerCase()) {
        dp[i][j] = dp[i - 1][j - 1];

      } else {
        int substitutionCost = dp[i - 1][j - 1] + 1;
        int deletionCost = dp[i - 1][j] + 1;
        int insertionCost = dp[i][j - 1] + 1;
        dp[i][j] = substitutionCost < (deletionCost < insertionCost) ? substitutionCost : (deletionCost < insertionCost ? deletionCost : insertionCost);
      }
    }
  }

  return dp[m][n];
}

