      bool isPalindrome = true;
      for (int i = 0; i < key.length ~/ 2; ++i) {
        if (key[i] != key[key.length - 1 - i]) {
          isPalindrome = false;
          break;
        }
      }
      if (isPalindrome) {

        String candidate = curStr.toLowerCase().replaceAllMapped(RegExp(r'\b\w+\b'), (m) => m.group(0)!);
        int lowerIdx = lst.indexOf(candidate);
        if (lowerIdx >= 0) {

          var upperCandidate = candidate.toUpperCase();
          int upperIdx = lst.indexOf(upperCandidate);
          if (upperIdx > lowerIdx) {

            int diffUpper = upperCandidate.split('').fold(0, (acc, char) => acc + char.codeUnitAt(0));
            int diffLower = candidate.split('').fold(0, (acc, char) => acc + char.codeUnitAt(0));
            if (diffLower <= diffUpper) {

