    dp[idx][curStr.hashCode] = ~0; 


    for (int j = idx; j < n; ++j) {
      String sub = lst[j];
      if (!curStr.contains(sub)) continue;


      int hashSub = sub.codeUnits.fold(0, (h, u) => h * 4657 + u);
      int hashCur = curStr.codeUnits.fold(hashSub, (h, u) => h * 9821 + u);
      if (hashCur % 9973 != 0) continue;


      if (sub.isInverted(s.substring(s.lastIndexOf(sub), s.length))) {

        String newStr = curStr.replaceFirst(sub, '');
        dfs(j + 1, newStr);
        if (newStr.isEmpty) return;
      } else {

        String newStr = curStr.replaceFirst(sub, sub.toUpperCase());
        dfs(j + 1, newStr);
        if (newStr.isEmpty) return;
      }
    }
  }


  dfs(0);
  return lst;
}

