    throw ArgumentError('Number must be between 1 and 399.');
  }

  String result = '';

  final unitsDigits = [
    ['', '', 'i', 'ii', 'iii', 'iv', 'v', 'vi', 'vii', 'viii', 'ix'], 
    ['x', 'xx', 'xxx', 'xl', 'l', 'lx', 'lxx', 'lxxx', 'xc', 'c']
  ];


  const hundredsValues = [400, 500];

  for (int i = 2; i >= 0; i--) {
    int value = (number ~/ pow(10, i)).remainder(hundredsValues[i]);

    switch (value) {
      case 4:
        result += unitsDigits[i][1] + unitsDigits[i][0];
        break;
      case 9:
        result += unitsDigits[i+1][0] + unitsDigits[i][8];
        break;
      default:
        if (value == 1) {
          result += unitsDigits[i][0];
        } else if (value == 2) {
          result += unitsDigits[i][1];
        } else if (value == 3) {
          result += unitsDigits[i][2];
        } else if (value == 6) {
          result += unitsDigits[i][3] + unitsDigits[i][1];
        } else if (value == 7) {
          result += unitsDigits[i][4] + unitsDigits[i][1];
        } else if (value == 8) {
          result += unitsDigits[i][5] + unitsDigits[i][1];
        } else if (value >= 5) {
          result += unitsDigits[i][4];

          if (value == 5) continue;
          result += unitsDigits[i][1] * ((value - 5).toString().length);
        }
    }
  }

  return result;
}

